// ===== TerraCorridor W1 Segmenter (deterministic, fail-closed) =====
const input = $input.first().json;
const cfg = $('W1 · Corridor Config').first().json;

const SEGMENT_LENGTH_M = Number(cfg.segment_length_m) || 1000;
const EXCLUSION_M = Number(cfg.exclusion_band_m) || 30;
const STUDY_M = Number(cfg.study_strip_m) || 200;
const R = 6371e3;

const fetchedAt = new Date().toISOString();
const sourceKind = input.source_kind || 'overpass_live';
const sourceUrl = input.source_url || cfg.overpass_url;
const sourceHash = input.source_hash;

function deg2rad(deg) { return deg * (Math.PI / 180); }
function getDistanceFromLatLonInMeters(lat1, lon1, lat2, lon2) {
  const dLat = deg2rad(lat2 - lat1);
  const dLon = deg2rad(lon2 - lon1);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
function r7(n) { return Math.round(n * 1e7) / 1e7; }
function key(p) { return p.lat.toFixed(6) + ',' + p.lon.toFixed(6); }

// Deterministic 64-bit FNV-1a style hash (two 32-bit lanes) -> 16 hex chars
function stableHash(str) {
  let h1 = 0x811c9dc5, h2 = 0x01000193 ^ 0x5bd1e995;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x5bd1e995) >>> 0;
    h2 = (h2 ^ (h2 >>> 15)) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

function failClosed(message, extra) {
  return [{ json: Object.assign({
    batch_status: 'unverified',
    error_message: message,
    corridor_id: cfg.corridor_id,
    source_hash: sourceHash || '',
    source_url: sourceUrl,
    source_kind: sourceKind,
    fallback_reason: input.fallback_reason || '',
    fetched_at: fetchedAt,
    way_count: 0,
    route_length_m: 0,
    segment_count: 0,
    segments: [],
  }, extra || {}) }];
}

// ---- 1. Provenance + parse validation ----
if (typeof sourceHash !== 'string' || !/^[0-9a-f]{64}$/.test(sourceHash)) {
  return failClosed('Missing or invalid SHA-256 hash of the raw response');
}
let parsed;
try {
  parsed = typeof input.data === 'string' ? JSON.parse(input.data) : input.data;
} catch (e) {
  return failClosed('Raw response is not valid JSON: ' + e.message);
}
if (!parsed || !Array.isArray(parsed.elements)) {
  return failClosed('Response has no elements array' + (parsed && parsed.remark ? ' (remark: ' + parsed.remark + ')' : ''));
}

const ways = parsed.elements
  .filter(el => el && el.type === 'way' && el.tags && el.tags.man_made === 'pipeline')
  .sort((a, b) => a.id - b.id);
if (ways.length === 0) {
  return failClosed('No man_made=pipeline ways found in the corridor bbox');
}

// ---- 2. Strict coordinate validation (any bad coordinate fails the batch) ----
const cleanWays = [];
for (const w of ways) {
  if (!Array.isArray(w.geometry) || w.geometry.length < 2) {
    return failClosed('Way ' + w.id + ' has no usable geometry (need out geom)');
  }
  const pts = [];
  for (const g of w.geometry) {
    const lat = Number(g && g.lat), lon = Number(g && g.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat < -90 || lat > 90 || lon < -180 || lon > 180) {
      return failClosed('Way ' + w.id + ' contains an invalid coordinate');
    }
    const p = { lat, lon };
    if (pts.length === 0 || key(pts[pts.length - 1]) !== key(p)) pts.push(p);
  }
  const t = w.tags || {};
  const ident = String(t.name || t.ref || ((t.operator || '') + '|' + (t.substance || '')) || 'unnamed').toLowerCase();
  if (pts.length >= 2) cleanWays.push({ id: w.id, pts, ident });
}
if (cleanWays.length === 0) return failClosed('All pipeline ways collapsed to fewer than 2 points');

function lineLength(pts) {
  let d = 0;
  for (let i = 1; i < pts.length; i++) d += getDistanceFromLatLonInMeters(pts[i - 1].lat, pts[i - 1].lon, pts[i].lat, pts[i].lon);
  return d;
}

// ---- 3. Stitch ways into continuous chains, keep the longest as the corridor ----
// Only join ways of the same pipeline identity, and only through simple (degree-2) joints,
// so separate pipelines or branches in a dense network are never chained together.
const degree = {};
for (const w of cleanWays) {
  for (const p of [w.pts[0], w.pts[w.pts.length - 1]]) {
    const k = w.ident + '#' + key(p);
    degree[k] = (degree[k] || 0) + 1;
  }
}
function joinable(ident, p) { return degree[ident + '#' + key(p)] === 2; }
const used = new Set();
const chains = [];
const byLen = cleanWays.slice().sort((a, b) => (lineLength(b.pts) - lineLength(a.pts)) || (a.id - b.id));
for (const seed of byLen) {
  if (used.has(seed.id)) continue;
  used.add(seed.id);
  let chain = seed.pts.slice();
  const wayIds = [seed.id];
  let extended = true;
  while (extended) {
    extended = false;
    for (const w of cleanWays) {
      if (used.has(w.id) || w.ident !== seed.ident) continue;
      const head = key(chain[0]), tail = key(chain[chain.length - 1]);
      const ws = key(w.pts[0]), we = key(w.pts[w.pts.length - 1]);
      const tailOk = joinable(seed.ident, chain[chain.length - 1]);
      const headOk = joinable(seed.ident, chain[0]);
      if (!tailOk && !headOk) break;
      if (tailOk && ws === tail) chain = chain.concat(w.pts.slice(1));
      else if (tailOk && we === tail) chain = chain.concat(w.pts.slice().reverse().slice(1));
      else if (headOk && we === head) chain = w.pts.slice(0, -1).concat(chain);
      else if (headOk && ws === head) chain = w.pts.slice().reverse().slice(0, -1).concat(chain);
      else continue;
      used.add(w.id); wayIds.push(w.id); extended = true;
    }
  }
  chains.push({ pts: chain, wayIds, ident: seed.ident, length: lineLength(chain) });
}
chains.sort((a, b) => (b.length - a.length) || (Math.min(...a.wayIds) - Math.min(...b.wayIds)));
let route = chains[0].pts;
// Canonical orientation: west -> east (then south -> north) so IDs are stable between runs
const s0 = route[0], e0 = route[route.length - 1];
if (s0.lon > e0.lon || (s0.lon === e0.lon && s0.lat > e0.lat)) route = route.slice().reverse();

// ---- 4. Cumulative haversine distance + 1 km cuts ----
const cum = [0];
for (let i = 1; i < route.length; i++) cum.push(cum[i - 1] + getDistanceFromLatLonInMeters(route[i - 1].lat, route[i - 1].lon, route[i].lat, route[i].lon));
const total = cum[cum.length - 1];
if (!(total > 0)) return failClosed('Route has zero length');

function pointAt(dist) {
  let i = 1;
  while (i < cum.length - 1 && cum[i] < dist) i++;
  const span = cum[i] - cum[i - 1];
  const t = span > 0 ? (dist - cum[i - 1]) / span : 0;
  return { lat: route[i - 1].lat + t * (route[i].lat - route[i - 1].lat), lon: route[i - 1].lon + t * (route[i].lon - route[i - 1].lon) };
}
function sliceLine(d0, d1) {
  const pts = [pointAt(d0)];
  for (let i = 0; i < route.length; i++) if (cum[i] > d0 && cum[i] < d1) pts.push(route[i]);
  pts.push(pointAt(d1));
  return pts;
}

// ---- 5. Offset polygons in a local metric frame ----
function offsetLine(pts, d) {
  const lat0 = pts[0].lat, lon0 = pts[0].lon, k = Math.cos(deg2rad(lat0));
  const xy = pts.map(p => ({ x: deg2rad(p.lon - lon0) * R * k, y: deg2rad(p.lat - lat0) * R }));
  const out = [];
  for (let i = 0; i < xy.length; i++) {
    const prev = xy[Math.max(0, i - 1)], next = xy[Math.min(xy.length - 1, i + 1)];
    const a = i > 0 ? norm(xy[i].x - prev.x, xy[i].y - prev.y) : null;
    const b = i < xy.length - 1 ? norm(next.x - xy[i].x, next.y - xy[i].y) : null;
    let nx, ny, scale = 1;
    if (a && b) {
      const n1 = { x: -a.y, y: a.x }, n2 = { x: -b.y, y: b.x };
      const m = norm(n1.x + n2.x, n1.y + n2.y) || n2;
      const cosHalf = m.x * n2.x + m.y * n2.y;
      scale = Math.min(1 / Math.max(cosHalf, 1e-6), 4); // clamp sharp miters
      nx = m.x; ny = m.y;
    } else {
      const t = a || b;
      nx = -t.y; ny = t.x;
    }
    const ox = xy[i].x + nx * d * scale, oy = xy[i].y + ny * d * scale;
    out.push([r7(lon0 + (ox / (R * k)) * 180 / Math.PI), r7(lat0 + (oy / R) * 180 / Math.PI)]);
  }
  return out;
}
function norm(x, y) { const l = Math.hypot(x, y); return l > 0 ? { x: x / l, y: y / l } : null; }
function ring(inner, outer) { // inner forward + outer reversed, closed
  const r = inner.concat(outer.slice().reverse());
  r.push(r[0]);
  return r;
}

const segments = [];
const nSeg = Math.ceil(total / SEGMENT_LENGTH_M - 1e-9);
for (let s = 0; s < nSeg; s++) {
  const d0 = s * SEGMENT_LENGTH_M;
  const d1 = Math.min((s + 1) * SEGMENT_LENGTH_M, total);
  if (d1 - d0 < 1) continue; // drop sub-metre slivers
  const line = sliceLine(d0, d1);
  const leftEx = offsetLine(line, EXCLUSION_M), rightEx = offsetLine(line, -EXCLUSION_M);
  const leftSt = offsetLine(line, EXCLUSION_M + STUDY_M), rightSt = offsetLine(line, -(EXCLUSION_M + STUDY_M));
  const all = leftSt.concat(rightSt);
  const bbox = {
    west: Math.min(...all.map(c => c[0])), east: Math.max(...all.map(c => c[0])),
    south: Math.min(...all.map(c => c[1])), north: Math.max(...all.map(c => c[1])),
  };
  const a = line[0], b = line[line.length - 1];
  const idSeed = [cfg.corridor_id, a.lat.toFixed(6), a.lon.toFixed(6), b.lat.toFixed(6), b.lon.toFixed(6)].join('|');
  const geometry = {
    type: 'FeatureCollection',
    features: [
      { type: 'Feature', properties: { zone: 'centreline' }, geometry: { type: 'LineString', coordinates: line.map(p => [r7(p.lon), r7(p.lat)]) } },
      { type: 'Feature', properties: { zone: 'cer_exclusion_band', half_width_m: EXCLUSION_M }, geometry: { type: 'Polygon', coordinates: [ring(leftEx, rightEx)] } },
      { type: 'Feature', properties: { zone: 'study_strip', inner_offset_m: EXCLUSION_M, outer_offset_m: EXCLUSION_M + STUDY_M }, geometry: { type: 'MultiPolygon', coordinates: [[ring(leftEx, leftSt)], [ring(rightEx, rightSt)]] } },
    ],
  };
  segments.push({
    segment_id: 'seg_' + stableHash(idSeed),
    corridor_id: cfg.corridor_id,
    segment_index: s,
    lat_start: r7(a.lat), lon_start: r7(a.lon),
    lat_end: r7(b.lat), lon_end: r7(b.lon),
    length_m: Math.round((d1 - d0) * 100) / 100,
    polygon_geometry_json: JSON.stringify(geometry),
    bbox_south: bbox.south, bbox_west: bbox.west, bbox_north: bbox.north, bbox_east: bbox.east,
    status: 'active',
    source_hash: sourceHash,
    source_kind: sourceKind,
    generated_at: fetchedAt,
  });
}
if (segments.length === 0) return failClosed('Segmentation produced no segments');
const ids = new Set(segments.map(x => x.segment_id));
if (ids.size !== segments.length) return failClosed('Segment ID collision detected');

return [{ json: {
  batch_status: 'verified',
  error_message: '',
  corridor_id: cfg.corridor_id,
  source_hash: sourceHash,
  source_url: sourceUrl,
  source_kind: sourceKind,
  fallback_reason: input.fallback_reason || '',
  fetched_at: fetchedAt,
  way_count: chains[0].wayIds.length,
  route_identity: chains[0].ident,
  route_way_ids: chains[0].wayIds.slice().sort((x, y) => x - y),
  route_length_m: Math.round(total * 100) / 100,
  segment_count: segments.length,
  segments,
} }];

// ===== W2: select + validate the segment batch (fail-closed) =====
const cfg = $('W2 · W2 Config').first().json;
const rows = $('W2 · Get Segments').all().map(i => i.json).filter(r => r && typeof r.segment_id === 'string' && r.segment_id);
const priorRows = $('W2 · Get Prior Baselines').all().map(i => i.json).filter(r => r && r.segment_id);

// De-duplicate by segment_id (keep the most recently generated row)
const byId = {};
for (const r of rows) {
  const prev = byId[r.segment_id];
  if (!prev || String(r.generated_at || '') > String(prev.generated_at || '')) byId[r.segment_id] = r;
}
const wanted = Array.isArray(cfg.segment_ids) ? cfg.segment_ids.map(String).filter(Boolean) : [];
let selected;
if (wanted.length) {
  const missing = wanted.filter(id => !byId[id]);
  if (missing.length) {
    throw new Error('Fail closed: ' + missing.length + ' requested segment(s) not found in corridor_segments for corridor ' + cfg.corridor_id + ': ' + missing.slice(0, 10).join(', '));
  }
  selected = wanted.map(id => byId[id]);
} else {
  selected = Object.values(byId).filter(r => r.status === 'active');
}
if (selected.length === 0) {
  throw new Error('Fail closed: no active segments found for corridor ' + cfg.corridor_id + ' - run W1 first');
}
selected.sort((a, b) => (Number(a.segment_index) - Number(b.segment_index)) || a.segment_id.localeCompare(b.segment_id));

const priorById = {};
for (const p of priorRows) priorById[p.segment_id] = p;

const CELL = Number(cfg.grid_cell_deg) || 0.1;
const NDVI_EVALSCRIPT = [
  '//VERSION=3',
  'function setup() {',
  '  return { input: [{ bands: ["B04", "B08", "SCL", "dataMask"] }],',
  '    output: [{ id: "ndvi", bands: 1, sampleType: "FLOAT32" }, { id: "dataMask", bands: 1 }] };',
  '}',
  'function evaluatePixel(s) {',
  '  const ndvi = (s.B08 + s.B04) > 0 ? (s.B08 - s.B04) / (s.B08 + s.B04) : 0;',
  '  const bad = [0, 1, 3, 8, 9, 10, 11].indexOf(s.SCL) >= 0;',
  '  return { ndvi: [ndvi], dataMask: [s.dataMask && !bad ? 1 : 0] };',
  '}',
].join('\n');

function num(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }

return selected.map(r => {
  const errors = [];
  const lat0 = num(r.lat_start), lon0 = num(r.lon_start), lat1 = num(r.lat_end), lon1 = num(r.lon_end), len = num(r.length_m);
  if ([lat0, lon0, lat1, lon1].some(v => v === null)) errors.push('segment has invalid start/end coordinates');
  if (!(len > 0)) errors.push('segment has invalid length_m');
  let studyStrip = null;
  try {
    const g = JSON.parse(r.polygon_geometry_json);
    const f = (g.features || []).find(x => x.properties && x.properties.zone === 'study_strip');
    if (f && f.geometry && f.geometry.type === 'MultiPolygon') studyStrip = f.geometry;
  } catch (e) { /* handled below */ }
  if (!studyStrip) errors.push('segment has no study_strip polygon');

  const cLat = lat0 !== null && lat1 !== null ? (lat0 + lat1) / 2 : 0;
  const cLon = lon0 !== null && lon1 !== null ? (lon0 + lon1) / 2 : 0;
  const cellLat = Math.round(cLat / CELL) * CELL, cellLon = Math.round(cLon / CELL) * CELL;
  const prior = priorById[r.segment_id] || {};

  return { json: {
    segment_id: r.segment_id,
    corridor_id: r.corridor_id || cfg.corridor_id,
    segment_index: Number(r.segment_index),
    length_m: len,
    lat_start: lat0, lon_start: lon0, lat_end: lat1, lon_end: lon1,
    centroid_lat: Math.round(cLat * 1e6) / 1e6,
    centroid_lon: Math.round(cLon * 1e6) / 1e6,
    cell_key: cellLat.toFixed(2) + '_' + cellLon.toFixed(2),
    cell_lat: Number(cellLat.toFixed(2)),
    cell_lon: Number(cellLon.toFixed(2)),
    segment_source_hash: r.source_hash || '',
    valid: errors.length === 0,
    validation_errors: errors,
    elevation_url: cfg.elevation_url + '?latitude=' + lat0 + ',' + lat1 + '&longitude=' + lon0 + ',' + lon1,
    ndvi_request: {
      input: {
        bounds: { geometry: studyStrip || { type: 'Polygon', coordinates: [] }, properties: { crs: 'http://www.opengis.net/def/crs/OGC/1.3/CRS84' } },
        data: [{ type: 'sentinel-2-l2a', dataFilter: { maxCloudCoverage: Number(cfg.ndvi_max_cloud) || 60 } }],
      },
      aggregation: {
        timeRange: { from: cfg.ndvi_from + 'T00:00:00Z', to: cfg.ndvi_to + 'T00:00:00Z' },
        aggregationInterval: { of: 'P1M' },
        evalscript: NDVI_EVALSCRIPT,
        resx: 0.0001,
        resy: 0.0001,
      },
    },
    prior_ndvi_series_json: prior.ndvi_series_json || '',
    prior_ndvi_hash: prior.ndvi_hash || '',
    prior_ndvi_source: prior.ndvi_source || '',
    // Mapped waterway crossings, loaded by scripts/fetch-crossings.js. null = never checked, '[]' = checked, none mapped.
    crossings_json: typeof prior.crossings_json === 'string' && prior.crossings_json.trim() ? prior.crossings_json : null,
  } };
});

// ===== Plan grid cells: reuse cached cell climate, fetch at most N new cells per run =====
// Historical archive (1995-2025) and CMIP6 projections are static datasets, so a cell is
// downloaded once and reused. The Open-Meteo free tier allows ~1 new cell (archive + climate) per minute.
const cfg = $('W2 · W2 Config').first().json;
const segs = $('W2 · Select Batch Segments').all().map(i => i.json).filter(s => s.valid);
if (segs.length === 0) throw new Error('Fail closed: no segment in the batch passed geometry validation, nothing to score');
const cachedRows = $('W2 · Get Cached Cells').all().map(i => i.json).filter(r => r && r.cell_key);
const SIG = [cfg.baseline_start, cfg.baseline_end, cfg.projection_start, cfg.projection_end, cfg.climate_models, 'v3'].join('|') // v2 added humidity (wildfire) and dry-soil / dry-spell metrics (drought); v3 = non-overlapping windows (2026-2030, 2031-2035);
// v1 and v2 cells were averaged over overlapping windows (2026-2030, 2026-2035). Their 10-year ratios mean something
// different, so they are NOT reused: an old cell is refetched (or seeded from a laptop run), never silently relabelled.
const SIG_V1 = null;
const MAX = Number.isFinite(Number(cfg.max_cell_fetches_per_run)) ? Number(cfg.max_cell_fetches_per_run) : 1;

const cache = {};
for (const r of cachedRows) {
  if (r.config_signature !== SIG && r.config_signature !== SIG_V1) continue;
  if (cache[r.cell_key] && cache[r.cell_key].sig === SIG) continue; // one current-signature row per cell
  try {
    const archive = JSON.parse(r.archive_metrics_json);
    const climate = JSON.parse(r.climate_metrics_json);
    if (archive && archive.ok && climate && climate.ok) cache[r.cell_key] = { archive, climate, fetched_at: r.fetched_at, sig: r.config_signature };
  } catch (e) { /* corrupt cache row -> refetch */ }
}

const cells = {};
for (const s of segs) {
  if (!cells[s.cell_key]) cells[s.cell_key] = { cell_key: s.cell_key, lat: s.cell_lat, lon: s.cell_lon, segment_ids: [] };
  cells[s.cell_key].segment_ids.push(s.segment_id);
}
let fetching = 0;
return Object.keys(cells).sort().map(k => {
  const c = cells[k];
  c.config_signature = SIG;
  c.archive_url = cfg.archive_url + '?latitude=' + c.lat + '&longitude=' + c.lon +
    '&start_date=' + cfg.baseline_start + '&end_date=' + cfg.baseline_end +
    '&daily=precipitation_sum,temperature_2m_max,temperature_2m_min,soil_moisture_0_to_7cm_mean,relative_humidity_2m_min&timezone=UTC';
  c.climate_url = cfg.climate_url + '?latitude=' + c.lat + '&longitude=' + c.lon +
    '&start_date=' + cfg.baseline_start + '&end_date=' + cfg.projection_end +
    '&models=' + cfg.climate_models +
    '&daily=precipitation_sum,temperature_2m_max,temperature_2m_min,soil_moisture_0_to_10cm_mean,relative_humidity_2m_min';
  if (cache[k]) return { json: Object.assign(c, { fetch: false, cache_status: 'cached', cache_signature: 'v3', archive: cache[k].archive, climate: cache[k].climate, cached_at: cache[k].fetched_at || '' }) };
  if (fetching < MAX) { fetching++; return { json: Object.assign(c, { fetch: true, cache_status: 'fetching' }) }; }
  const msg = 'deferred: grid cell ' + k + ' not cached yet (Open-Meteo free tier allows ' + MAX + ' new cell per run); it is fetched on a later run';
  return { json: Object.assign(c, { fetch: false, cache_status: 'deferred', archive: { ok: false, error: msg, hash: '' }, climate: { ok: false, error: msg, hash: '', models: {} } }) };
});

// ===== shared W2 helpers =====
const cfg = $('W2 · W2 Config').first().json;
const now = new Date().toISOString();
const MODELS = String(cfg.climate_models).split(',').map(s => s.trim()).filter(Boolean);
const W = { R: Number(cfg.weight_r), F: Number(cfg.weight_f), W: Number(cfg.weight_w), V: Number(cfg.weight_v), S: Number(cfg.weight_s) };
const RATIO_FULL = Number(cfg.ratio_full_score_increase) || 0.5; // +50% vs baseline => component score 1 (provisional, see docs/THRESHOLDS.md)
const NDVI_FULL = Number(cfg.ndvi_drop_full_score) || 0.1;
const SLOPE_FULL = Number(cfg.slope_full_score_pct) || 10;
const AMBER = Number(cfg.amber_min) || 40, RED = Number(cfg.red_above) || 65;
const BASE_END_YEAR = Number(String(cfg.baseline_end).slice(0, 4));
const BASE_START_YEAR = Number(String(cfg.baseline_start).slice(0, 4));
const HORIZONS = [
  { years: 5, start: String(cfg.projection_start).slice(0, 4), end: String(Number(String(cfg.projection_start).slice(0, 4)) + 4) },
  // Non-overlapping: the 10-year view is the second five years only (2031-2035), so it can disagree with the first.
  { years: 10, start: String(Number(String(cfg.projection_start).slice(0, 4)) + 5), end: String(Number(String(cfg.projection_start).slice(0, 4)) + 9) },
];

const clamp01 = x => Math.max(0, Math.min(1, x));
const r3 = x => (x === null || x === undefined || !Number.isFinite(x)) ? null : Math.round(x * 1000) / 1000;
const r1 = x => (x === null || x === undefined || !Number.isFinite(x)) ? null : Math.round(x * 10) / 10;
function pct(sorted, p) {
  if (!sorted.length) return null;
