        r.ratios[h.years] = w ? { rain: ratio(w.rain, m.base.rain), ft: ratio(w.ft, m.base.ft), sat: m.base.sat === null ? null : ratio(w.sat, m.base.sat),
          dry: m.base.dry === null || w.dry === null ? null : ratio(w.dry, m.base.dry),
