    if (rhOk) {
      const vr = v.filter(i => Number.isFinite(rh[i]));
      if (vr.length >= 0.9 * n) fire = vr.filter(i => pr[i] < FIRE.dryMm && tx[i] >= FIRE.tmaxC && rh[i] <= FIRE.rhMinPct).length / (vr.length / 365.25);
    }
    return { rain, ft, sat, dry, spell, fire };
  }
  const base = rates(idxBase);
  const windows = {};
  for (const h of HORIZONS) {
    const idx = [];
    for (let i = 0; i < time.length; i++) { const y = time[i].slice(0, 4); if (y >= h.start && y <= h.end) idx.push(i); }
    windows[h.years] = rates(idx);
  }
  return { ok: !!base, error: base ? '' : 'baseline rates unavailable', rainP95, soilP90, soilP10, base, windows };
}
function ratio(proj, base) {
  if (proj === null || proj === undefined || base === null || base === undefined) return null;
  return Math.min(3, proj / Math.max(base, 0.1));
}


// ===== W2: deterministic risk scoring (fail-closed) =====
// Ground failure = 100 * (0.35R + 0.20F + 0.15W + 0.20V + 0.10S).
// River crossing, wildfire weather and drought are scored on their own (same rules as src/engine.js).
// The segment's risk_score and tier are its WORST hazard, never a blend. A hazard with no input data is left out
// and its reason is recorded in hazards_json.status; it is never scored as zero.
const HAZ_W = { drought: { drySoil: 0.6, drySpell: 0.4 }, wildfire: { change: 0.5, level: 0.4, fuel: 0.1 }, crossing: { size: 0.4, rain: 0.35, flow: 0.25 } };
const FIRE_DAYS_FULL = 20, PEAK_FLOW_FULL = 200, CROSSING_SIZE = { river: 1, canal: 0.6, stream: 0.4, drain: 0.3 };
function weighted(f, wts) { let s = 0, w = 0; for (const k of Object.keys(wts)) if (f[k] !== null && f[k] !== undefined) { s += wts[k] * f[k]; w += wts[k]; } return w ? Math.round(1000 * s / w) / 10 : null; }
const sgn = x => (x > 0 ? '+' : '') + x;
const pctInt = x => (x === null || x === undefined) ? null : Math.round((x - 1) * 100);
const segs = $('W2 · Select Batch Segments').all().map(i => i.json);
const ndviResp = $('W2 · Hash NDVI').all().map(i => i.json);
const elevResp = $('W2 · Hash Elevation').all().map(i => i.json);
const cellRecords = $input.all().map(i => i.json).filter(r => r && r.cell_key);

const cellInfo = {};
const sourceRows = [];
for (const rec of cellRecords) {
  const a = rec.archive || { ok: false, error: 'no archive result' };
  const c = rec.climate || { ok: false, error: 'no climate result', models: {} };
  if (rec.cache_status === 'fetched') {
    sourceRows.push({ source_kind: 'open_meteo_archive', source_url: rec.archive_url, source_hash: a.ok ? a.hash : '', batch_status: a.ok ? 'verified' : 'failed', error_message: a.ok ? '' : a.error });
    sourceRows.push({ source_kind: 'open_meteo_climate', source_url: rec.climate_url, source_hash: c.ok ? c.hash : '', batch_status: c.ok ? 'verified' : 'failed', error_message: c.ok ? '' : c.error });
  }
  const info = cellInfo[rec.cell_key] = { errors: [], models: {}, cache_status: rec.cache_status };
  if (a.ok) { info.archive = a; info.archive_hash = a.hash; } else info.errors.push('archive: ' + a.error);
  if (c.ok) { info.models = c.models || {}; info.climate_hash = c.hash; } else info.errors.push('climate: ' + c.error);
}

// ---- NDVI growing-season trend ----
function ndviFromStats(j) {
  const series = [];
  for (const iv of (j && j.data) || []) {
    if (iv.error) continue;
    const st = iv.outputs && iv.outputs.ndvi && iv.outputs.ndvi.bands && iv.outputs.ndvi.bands.B0 && iv.outputs.ndvi.bands.B0.stats;
    if (!st || !Number.isFinite(st.mean) || !(st.sampleCount > 0)) continue;
    const validFrac = (st.sampleCount - (st.noDataCount || 0)) / st.sampleCount;
    if (validFrac < 0.2) continue;
    series.push({ month: String(iv.interval.from).slice(0, 7), mean: r3(st.mean), valid_frac: r3(validFrac) });
  }
  return series;
}
function ndviTrend(series) {
  const byYear = {};
  for (const p of series) {
    const mo = Number(p.month.slice(5, 7));
    if (mo < 5 || mo > 9) continue;
    (byYear[p.month.slice(0, 4)] = byYear[p.month.slice(0, 4)] || []).push(p.mean);
  }
  const pts = Object.keys(byYear).filter(y => byYear[y].length >= 2).sort().map(y => ({ x: Number(y), y: byYear[y].reduce((a, b) => a + b, 0) / byYear[y].length }));
  if (pts.length < 4) return { ok: false, error: 'NDVI: fewer than 4 growing seasons with cloud-free data' };
  const mx = pts.reduce((a, p) => a + p.x, 0) / pts.length, my = pts.reduce((a, p) => a + p.y, 0) / pts.length;
  const slope = pts.reduce((a, p) => a + (p.x - mx) * (p.y - my), 0) / pts.reduce((a, p) => a + (p.x - mx) ** 2, 0);
  const span = pts[pts.length - 1].x - pts[0].x;
  return { ok: true, slope, drop: Math.max(0, -slope * span), years: pts.map(p => p.x) };
}

const out = [];
segs.forEach((s, i) => {
  const errors = (s.validation_errors || []).slice();
  // Elevation / slope
  const e = parseRaw(elevResp[i]);
  sourceRows.push({ source_kind: 'open_meteo_elevation', source_url: s.elevation_url, source_hash: e.ok ? e.hash : '', batch_status: e.ok ? 'verified' : 'failed', error_message: e.ok ? '' : e.error });
  let elev0 = null, elev1 = null, slopePct = null;
  if (e.ok && Array.isArray(e.json.elevation) && e.json.elevation.length === 2 && e.json.elevation.every(Number.isFinite) && s.length_m > 0) {
    elev0 = e.json.elevation[0]; elev1 = e.json.elevation[1];
    slopePct = Math.abs(elev1 - elev0) / s.length_m * 100;
  } else errors.push('elevation: ' + (e.ok ? 'unexpected response shape' : e.error));

  // NDVI (live -> cached previous live series -> unverified)
  const n = parseRaw(ndviResp[i]);
  sourceRows.push({ source_kind: 'cdse_sentinel2_ndvi', source_url: cfg.ndvi_url + '#' + s.segment_id, source_hash: n.ok ? n.hash : '', batch_status: n.ok ? 'verified' : 'failed', error_message: n.ok ? '' : n.error });
  let series = null, ndviSource = '', ndviHash = '', trend = null;
  if (n.ok) {
    series = ndviFromStats(n.json); trend = ndviTrend(series);
    if (trend.ok) { ndviSource = 'cdse_live'; ndviHash = n.hash; }
  }
  if ((!trend || !trend.ok) && s.prior_ndvi_series_json) {
    try {
      const cached = JSON.parse(s.prior_ndvi_series_json);
      const t2 = ndviTrend(cached);
      if (t2.ok) { series = cached; trend = t2; ndviSource = 'cache_previous_live'; ndviHash = s.prior_ndvi_hash; }
    } catch (err) { /* ignore broken cache */ }
  }
  if (!trend || !trend.ok) errors.push(n.ok ? (trend ? trend.error : 'NDVI: no data') : 'NDVI: ' + n.error + ' and no cached series');

  const cell = cellInfo[s.cell_key] || { errors: ['no climate data for cell ' + s.cell_key], models: {} };
  if (!s.valid) { /* validation errors already listed */ } else errors.push(...cell.errors);
  const arch = cell.archive;

  const V = trend && trend.ok ? clamp01(trend.drop / NDVI_FULL) : null;
  const S = slopePct !== null ? clamp01(slopePct / SLOPE_FULL) : null;
  const baselineStatusOk = errors.length === 0;

  const baselineRow = {
    segment_id: s.segment_id, corridor_id: s.corridor_id, cell_key: s.cell_key,
    centroid_lat: s.centroid_lat, centroid_lon: s.centroid_lon,
    baseline_period: cfg.baseline_start.slice(0, 4) + '-' + cfg.baseline_end.slice(0, 4),
    rain_p95_mm: arch ? r1(arch.rainP95) : null,
    extreme_rain_days_per_yr: arch ? r1(arch.base.rain) : null,
    freeze_thaw_days_per_yr: arch ? r1(arch.base.ft) : null,
    soil_p90_m3m3: arch ? r3(arch.soilP90) : null,
    saturation_days_per_yr: arch ? r1(arch.base.sat) : null,
    ndvi_series_json: series ? JSON.stringify(series) : '',
    ndvi_source: ndviSource || 'unavailable',
    ndvi_slope_per_yr: trend && trend.ok ? Math.round(trend.slope * 10000) / 10000 : null,
    ndvi_drop_5yr: trend && trend.ok ? r3(trend.drop) : null,
    elevation_start_m: elev0, elevation_end_m: elev1, slope_pct: r3(slopePct),
    archive_hash: cell.archive_hash || '', climate_hash: cell.climate_hash || '',
    ndvi_hash: ndviHash, elevation_hash: e.ok ? e.hash : '',
    status: baselineStatusOk ? 'verified' : 'unverified',
    error_message: errors.join('; '),
    computed_at: now,
  };

  HORIZONS.forEach(h => {
    const hErrors = errors.slice();
    const perModel = {};
    const okModels = MODELS.filter(m => cell.models[m] && cell.models[m].ok && cell.models[m].ratios[h.years]);
    if (okModels.length < 2) hErrors.push('climate: fewer than 2 of 3 CMIP6 models usable for ' + h.years + '-yr window');
    const mean = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
    const rr = mean(okModels.map(m => cell.models[m].ratios[h.years].rain).filter(Number.isFinite));
    const fr = mean(okModels.map(m => cell.models[m].ratios[h.years].ft).filter(Number.isFinite));
    const sr = mean(okModels.map(m => cell.models[m].ratios[h.years].sat).filter(Number.isFinite));
    const dryR = mean(okModels.map(m => cell.models[m].ratios[h.years].dry).filter(Number.isFinite));
    const spellR = mean(okModels.map(m => cell.models[m].ratios[h.years].spell).filter(Number.isFinite));
    const fireModels = okModels.filter(m => Number.isFinite(cell.models[m].ratios[h.years].fire));
    const fireR = mean(fireModels.map(m => cell.models[m].ratios[h.years].fire));
    if (sr === null) hErrors.push('climate: no model provided soil moisture');
    const comp = (x) => x === null ? null : clamp01((x - 1) / RATIO_FULL);
    const C = { R: comp(rr), F: comp(fr), W: comp(sr), V, S };
    const complete = hErrors.length === 0 && Object.values(C).every(v => v !== null);

    let score = null, tier = 'unverified', agreement = '', groundScore = null, topKey = '', hazardsJson = '';
    if (complete) {
      groundScore = Math.round(risk(C) * 10) / 10;
      score = groundScore;
      tier = tierOf(score);
      const tiers = [];
      for (const m of okModels) {
        const rt = cell.models[m].ratios[h.years];
        const cm = { R: comp(rt.rain), F: comp(rt.ft), W: rt.sat === null ? C.W : comp(rt.sat), V, S };
        const sc = Math.round(risk(cm) * 10) / 10;
        perModel[m] = { score: sc, tier: tierOf(sc), rain_ratio: r3(rt.rain), freeze_thaw_ratio: r3(rt.ft), saturation_ratio: r3(rt.sat), soil_from_ensemble: rt.sat === null };
        tiers.push(tierOf(sc));
      }
      const counts = {}; tiers.forEach(t => counts[t] = (counts[t] || 0) + 1);
      const maxAgree = Math.max(...Object.values(counts));
      agreement = (maxAgree === MODELS.length && okModels.length === MODELS.length) ? 'high' : (maxAgree >= 2 ? 'medium' : 'low');
    }
    if (complete) {
      const ab = (arch && arch.base) || {};
      const hz = {}, status = {};
      const drvs = [['Extreme-rain days', pctInt(rr), W.R * C.R], ['Freeze-thaw days', pctInt(fr), W.F * C.F], ['Wet-soil days', pctInt(sr), W.W * C.W]].sort((a, b) => b[2] - a[2]);
      const localTop = W.V * C.V >= W.S * C.S ? 'Plant cover -' + r3(trend.drop) + ' NDVI in 5 years' : 'Slope ' + r1(slopePct) + '%';
      hz.ground = { key: 'ground', label: 'Ground failure', score: groundScore,
        why: drvs[0][2] > Math.max(W.V * C.V, W.S * C.S) ? drvs[0][0] + ' ' + sgn(drvs[0][1]) + '%' : (Math.max(W.V * C.V, W.S * C.S) > 0 ? localTop : 'No change from baseline') };
      status.ground = 'scored';
      // Drought
      const fD = { drySoil: comp(dryR), drySpell: comp(spellR) };
      const dS = weighted(fD, HAZ_W.drought);
      if (dS === null) status.drought = 'unavailable: ' + (!Number.isFinite(ab.spell) ? 'this cell was cached before dry-soil and dry-spell metrics were added, refetch it' : 'no climate model provided soil moisture or rain for this window');
      else {
        const pSoil = pctInt(dryR), pSpell = pctInt(spellR);
        hz.drought = { key: 'drought', label: 'Drought', score: dS, factors: fD,
          why: pSoil !== null && (pSpell === null || Math.abs(pSoil) >= Math.abs(pSpell)) ? 'Dry-soil days ' + sgn(pSoil) + '%' : 'Longest dry spell ' + sgn(pSpell) + '%',
          change: { drySoil: pSoil, drySpell: pSpell },
          base: { drySoilDaysPerYr: r1(ab.dry), drySpellDays: r1(ab.spell) },
          proj: { drySoilDaysPerYr: dryR !== null && Number.isFinite(ab.dry) ? r1(dryR * ab.dry) : null, drySpellDays: spellR !== null && Number.isFinite(ab.spell) ? r1(spellR * ab.spell) : null } };
        status.drought = dryR === null ? 'scored on dry spells only: no model soil moisture' : 'scored';
      }
      // Wildfire weather
      if (fireR === null || !Number.isFinite(ab.fire)) status.wildfire = 'unavailable: ' + (!Number.isFinite(ab.fire) ? 'no observed humidity in the cached baseline' : 'no climate model provided humidity for this window');
      else {
        const projF = fireR * ab.fire;
        const nm = (series || []).map(p => p.mean).filter(Number.isFinite);
        const ndviMean = nm.length ? nm.reduce((a, b) => a + b, 0) / nm.length : null;
        const fF = { change: clamp01((fireR - 1) / 2), level: clamp01(projF / FIRE_DAYS_FULL), fuel: ndviMean === null ? null : clamp01((ndviMean - 0.3) / 0.4) };
        hz.wildfire = { key: 'wildfire', label: 'Wildfire weather', score: weighted(fF, HAZ_W.wildfire), factors: fF,
          why: 'Fire-weather days ' + r1(ab.fire) + ' to ' + r1(projF) + ' a year (' + sgn(pctInt(fireR)) + '%)',
          change: { fireDays: pctInt(fireR) }, base: { fireWeatherDaysPerYr: r1(ab.fire) }, proj: { fireWeatherDaysPerYr: r1(projF) },
          fuelNdvi: ndviMean === null ? null : Math.round(ndviMean * 100) / 100, models_with_humidity: fireModels.length };
        status.wildfire = 'scored (' + fireModels.length + ' of ' + okModels.length + ' models have humidity)';
      }
      // River crossing: only where a mapped waterway crosses the centreline
      let xs = null;
      if (s.crossings_json !== null && s.crossings_json !== undefined) { try { const p = JSON.parse(s.crossings_json); if (Array.isArray(p)) xs = p; } catch (err) { xs = null; } }
      if (xs === null) status.crossing = 'not checked: no waterway map loaded for this segment';
      else if (!xs.length) status.crossing = 'not applicable: no mapped waterway crosses this segment';
      else {
        const size = Math.max(...xs.map(x => CROSSING_SIZE[x.kind] !== undefined ? CROSSING_SIZE[x.kind] : 0.4));
        const flows = xs.map(x => x.peakFlowM3s).filter(Number.isFinite);
        const peak = flows.length ? Math.max(...flows) : null;
        const fX = { size, rain: C.R, flow: peak === null ? null : clamp01(peak / PEAK_FLOW_FULL) };
        const big = xs.reduce((a, x) => ((CROSSING_SIZE[x.kind] || 0) > (CROSSING_SIZE[a.kind] || 0) ? x : a), xs[0]);
        hz.crossing = { key: 'crossing', label: 'River crossing', score: weighted(fX, HAZ_W.crossing), factors: fX,
          why: 'Crosses ' + (big.name || 'a ' + big.kind) + (peak !== null ? ' (peak flow ' + Math.round(peak) + ' m³/s)' : '') + ', heavy rain ' + sgn(pctInt(rr)) + '%',
          crossings: xs.map(x => ({ name: x.name || null, kind: x.kind, peakFlowM3s: Number.isFinite(x.peakFlowM3s) ? x.peakFlowM3s : null, at: x.at || null })) };
        status.crossing = peak === null ? 'scored without river flow: no discharge data at the crossing' : 'scored';
      }
      let top = hz.ground;
      for (const k of Object.keys(hz)) { hz[k].tier = tierOf(hz[k].score); if (hz[k].score > top.score) top = hz[k]; }
      score = top.score; tier = tierOf(score); topKey = top.key;
      hazardsJson = JSON.stringify({ top: topKey, ground_score: groundScore, hazards: hz, status,
        base: { drySoilDaysPerYr: r1(ab.dry), drySpellDays: r1(ab.spell), fireWeatherDaysPerYr: r1(ab.fire) },
        crossings: xs, ratio_full: RATIO_FULL, tiers: { amber: AMBER, red: RED } });
    }
    const pctTxt = x => x === null ? 'n/a' : ((x >= 1 ? '+' : '') + Math.round((x - 1) * 100) + '%');
    const facts = complete ? [
      'Segment ' + s.segment_index + ' (' + s.segment_id + '), ' + h.years + '-year horizon ' + h.start + '-' + h.end + ':',
      'risk score ' + score + '/100 (' + tier + '), set by the worst hazard: ' + topKey + '. Ground-failure score ' + groundScore + '. CMIP6 model agreement ' + agreement + '.',
      'Extreme rain days ' + pctTxt(rr) + ' vs ' + baselineRow.baseline_period + ' baseline;',
      'freeze-thaw days ' + pctTxt(fr) + ';',
      'soil saturation days ' + pctTxt(sr) + ';',
      'Sentinel-2 growing-season NDVI drop ' + r3(trend.drop) + ' over ' + trend.years[0] + '-' + trend.years[trend.years.length - 1] + ';',
      'terrain slope ' + r1(slopePct) + '%.',
    ].join(' ') : '';

    out.push({ json: {
      prediction_id: s.segment_id + '_h' + h.years,
      segment_id: s.segment_id,
      corridor_id: s.corridor_id,
      segment_index: s.segment_index,
      horizon_years: h.years,
      window_start: h.start + '-01-01',
      window_end: h.end + '-12-31',
      risk_score: score,
      tier,
      hazard: topKey,
      ground_score: groundScore,
      hazards_json: hazardsJson,
      model_agreement: agreement,
      score_r: r3(C.R), score_f: r3(C.F), score_w: r3(C.W), score_v: r3(C.V), score_s: r3(C.S),
      rain_ratio: r3(rr), freeze_thaw_ratio: r3(fr), saturation_ratio: r3(sr),
      model_scores_json: JSON.stringify(perModel),
      explanation: '',
      needs_explanation: tier === 'amber' || tier === 'red',
      explain_facts: facts,
      archive_hash: cell.archive_hash || '', climate_hash: cell.climate_hash || '',
      ndvi_hash: ndviHash, elevation_hash: e.ok ? e.hash : '',
      segment_source_hash: s.segment_source_hash,
      status: complete ? 'verified' : 'unverified',
      error_message: hErrors.join('; '),
      computed_at: now,
      baseline_row: h.years === 5 ? baselineRow : null,
    } });
  });
});

// Attach provenance rows to the first item (logged once by the audit branch)
const seen = new Set();
const srcRows = sourceRows.filter(r => { const k = r.source_kind + '|' + r.source_url; if (seen.has(k)) return false; seen.add(k); return true; })
  .map(r => Object.assign({ corridor_id: cfg.corridor_id, fetched_at: now, segment_count: segs.length, fallback_reason: r.source_kind === 'cdse_sentinel2_ndvi' && r.batch_status === 'failed' ? 'live NDVI failed; previous live series used if cached, else segment unverified' : '' }, r));
if (out.length) out[0].json.source_rows = srcRows;
return out;

parameters.text:
=Write the dashboard explanation for this pipeline corridor segment.

Metrics:
{{ $json.explain_facts }}

parameters.jsCode:
// Reads corridor state from the shared W2 tables and keeps segments whose 5- or 10-year tier is amber, red or red-uncertain.
// An operator override for that horizon replaces the model tier. Segments are grouped by 10 km climate cell
// so each cell needs one forecast call.
// Tables: corridor_predictions (W2, one row per segment and horizon_years 5 or 10), corridor_baselines (W2, one row per segment),
// corridor_watch (W3 near-term state and W4 tier overrides). Unverified predictions are skipped here: W2 already marks them unverified.
const FLAG = ['amber', 'red', 'red-uncertain'];
const RANK = { red: 3, 'red-uncertain': 3, amber: 2 };
const WEIGHT = { rain: 0.35, freezeThaw: 0.20, saturation: 0.15, vegetation: 0.20, slope: 0.10 }; // same weights as the W2 Config node
const rows = (name) => $(name).all().map((i) => i.json).filter((r) => r && !r.error && Object.keys(r).length > 0);
const n = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));
const r1 = (x) => (x == null ? null : Math.round(x * 10) / 10);
const watch = Object.fromEntries(rows('Get watch state').filter((s) => s.segment_id).map((s) => [s.segment_id, s]));
const baseBySeg = Object.fromEntries(rows('Get baselines').filter((b) => b.segment_id).map((b) => [b.segment_id, b]));
const segs = {};
for (const [id, b] of Object.entries(baseBySeg)) {
  segs[id] = { ...(watch[id] || {}), segment_id: id, slope_pct: n(b.slope_pct), cell: b.cell_key || null, lat: n(b.centroid_lat), lon: n(b.centroid_lon) };
}
// One threshold set per climate cell (W2 stores the 1995-2025 annual rain p95 and soil p90; no monthly table, so the annual value is used).
const bases = {};
for (const b of Object.values(baseBySeg)) {
  if (b.cell_key && !bases[b.cell_key]) bases[b.cell_key] = { cell: b.cell_key, lat: n(b.centroid_lat), lon: n(b.centroid_lon), extreme_mm: n(b.rain_p95_mm), soil_wet_threshold: n(b.soil_p90_m3m3), monthly_thresholds_json: '' };
}
const parse = (v, d) => { try { return v ? JSON.parse(v) : d; } catch (e) { return d; } };
const driversFor = (p, b) => {
  const base = { rain: n(b.extreme_rain_days_per_yr), ft: n(b.freeze_thaw_days_per_yr), sat: n(b.saturation_days_per_yr) };
  const ratio = { rain: n(p.rain_ratio), ft: n(p.freeze_thaw_ratio), sat: n(p.saturation_ratio) };
  const pct = (x) => (x == null ? null : Math.round((x - 1) * 100));
  const proj = (k) => (base[k] != null && ratio[k] != null ? r1(base[k] * ratio[k]) : null);
  return [
    { key: 'rain', label: 'Extreme-rain days', change: pct(ratio.rain), base: base.rain, proj: proj('rain'), w: WEIGHT.rain * (n(p.score_r) || 0) },
    { key: 'freezeThaw', label: 'Freeze-thaw days', change: pct(ratio.ft), base: base.ft, proj: proj('ft'), w: WEIGHT.freezeThaw * (n(p.score_f) || 0) },
    { key: 'saturation', label: 'Wet-soil days', change: pct(ratio.sat), base: base.sat, proj: proj('sat'), w: WEIGHT.saturation * (n(p.score_w) || 0) },
    { key: 'vegetation', label: 'Vegetation change (NDVI, 5 yr)', change: n(b.ndvi_drop_5yr) == null ? null : -n(b.ndvi_drop_5yr), w: WEIGHT.vegetation * (n(p.score_v) || 0) },
    { key: 'slope', label: 'Slope', change: n(b.slope_pct), w: WEIGHT.slope * (n(p.score_s) || 0) },
  ].sort((a, c) => c.w - a.w);
};
const flagged = {};
for (const p of rows('Get predictions')) {
  if (!p.segment_id || (p.status && p.status !== 'verified')) continue;
  const horizon = 'y' + Number(p.horizon_years);
  if (horizon !== 'y5' && horizon !== 'y10') continue;
  const s = segs[p.segment_id] || {};
  const modelTier = p.tier === 'red' && p.model_agreement === 'low' ? 'red-uncertain' : p.tier;
  const tier = s.override_tier && (s.override_horizon || 'y10') === horizon ? s.override_tier : modelTier;
  if (!FLAG.includes(tier)) continue;
  const cur = flagged[p.segment_id];
  const better = !cur || RANK[tier] > RANK[cur.tier] || (RANK[tier] === RANK[cur.tier] && horizon === 'y10' && cur.horizon !== 'y10');
  if (!better) continue;
  const drivers = driversFor(p, baseBySeg[p.segment_id] || {});
  flagged[p.segment_id] = {
    segment_id: p.segment_id, tier, model_tier: modelTier, overridden: tier !== modelTier, horizon,
    score: n(p.risk_score), agreement: p.model_agreement || null, primary_driver: drivers[0] ? drivers[0].label : null, drivers_json: JSON.stringify(drivers),
    slope_pct: s.slope_pct != null ? s.slope_pct : null, cell: s.cell || null, lat: s.lat, lon: s.lon,
  };
}
const cells = {};
for (const f of Object.values(flagged)) {
  const key = f.cell || 'seg:' + f.segment_id;
  (cells[key] = cells[key] || []).push(f);
}
return Object.entries(cells).map(([cell, list]) => {
  const b = bases[cell] || null;
  const avg = (k) => { const v = list.map((x) => x[k]).filter((x) => x != null); return v.length ? v.reduce((a, c) => a + c, 0) / v.length : null; };
  const lat = b && b.lat != null ? b.lat : avg('lat');
  const lon = b && b.lon != null ? b.lon : avg('lon');
  return { json: {
    cell,
    lat: lat != null ? Number(lat).toFixed(4) : '',
    lon: lon != null ? Number(lon).toFixed(4) : '',
    has_baseline: !!b,
    annual: b ? { extreme_mm: b.extreme_mm, soil_wet_threshold: b.soil_wet_threshold } : { extreme_mm: null, soil_wet_threshold: null },
    monthly: b ? parse(b.monthly_thresholds_json, {}) : {},
    segments: list,
  } };
});

// Compares the 16-day forecast against each cell's seasonal thresholds from the 1995-2025 baseline:
// the month's 95th-percentile wet-day rain and 90th-percentile soil moisture (annual values if the month is missing).
// Fail-closed: no forecast or no baseline means 'unverified' (grey), never 'clear'.
// ---- Escalation policy (edit here; logged with every run) ----
// A long-range (5 or 10 year) tier is a PLANNING signal. It never drafts a work order on its own: the integrity manager
// requests those from the dashboard. A draft is only proposed when heavy weather is forecast in the next 16 days on
// ground that is already amber or red. DRY_RUN logs what would be drafted and calls Workflow 4 for nothing.
// MAX_DRAFTS_PER_RUN caps the drafts of one run, highest score first; the rest are logged as suppressed.
const DRY_RUN = true;
const MAX_DRAFTS_PER_RUN = 3;
const cells = $('WF3 · Select flagged segments').all().map((i) => i.json);
const fc = $input.all().map((i) => i.json || {});
const now = new Date().toISOString();
let cached = []; try { cached = $('WF3 · Get forecast cache').all().map(i => i.json); } catch (_) {}
const utcDay = now.slice(0, 10);
const complete = (f) => f && !f.error && f.daily && Array.isArray(f.daily.time) && f.daily.time.length > 0
  && f.daily.time.includes(utcDay) && Array.isArray(f.daily.precipitation_sum)
  && f.daily.time.length === f.daily.precipitation_sum.length
  && f.daily.precipitation_sum.every(x => typeof x === 'number' && Number.isFinite(x));

const r1 = (x) => (x == null ? null : Math.round(x * 10) / 10);
const out = [];
cells.forEach((c, k) => {
  let f = fc[k] || {};
  let forecastSource = 'live_open_meteo';
  if (!complete(f)) {
    const row = cached.filter(r => r.cell_key === c.cell && r.forecast_json)
      .sort((a,b) => String(b.forecast_fetched_at).localeCompare(String(a.forecast_fetched_at)))[0];
    const age = row ? Date.now() - Date.parse(row.forecast_fetched_at) : Infinity;
    let candidate; try { candidate = JSON.parse(row.forecast_json); } catch (_) {}
    if (age >= 0 && age <= 24 * 3600 * 1000 && complete(candidate)) { f = candidate; forecastSource = 'cached_open_meteo:' + row.forecast_fetched_at; }
  }
  const d = f.daily;
  const pr = (d && d.precipitation_sum) || [];
  const sm = (d && d.soil_moisture_0_to_7cm_mean) || [];
  const tmin = (d && d.temperature_2m_min) || [], tmax = (d && d.temperature_2m_max) || [];
  const apiOk = complete(f);
  const thr = (date) => {
    const m = (c.monthly || {})[String(Number(String(date).slice(5, 7)))] || {};
    return {
      rain: m.extreme_mm != null ? m.extreme_mm : c.annual.extreme_mm,
      soil: m.soil_wet_threshold != null ? m.soil_wet_threshold : c.annual.soil_wet_threshold,
      basis: m.extreme_mm != null ? 'monthly' : 'annual',
    };
  };
  let state, summary;
  const events = [];
  const stats = { max_precip_mm: null, max_precip_date: null, max_soil: null, wet_soil_days: 0, freeze_thaw_days: 0, days: d && d.time ? d.time.length : 0 };
  if (!apiOk) {
    state = 'unverified';
    const msg = f.error ? (f.error.message || f.error.description || JSON.stringify(f.error)) : 'missing, stale, or incomplete daily precipitation';
    summary = 'Forecast unavailable (' + String(msg).slice(0, 160) + '). Treated as unverified, not safe.';
  } else if (c.annual.extreme_mm == null) {
    state = 'unverified';
    summary = 'No baseline thresholds for cell ' + c.cell + '. Run Workflow 2 to sync baselines. Treated as unverified.';
  } else {
    let lastMulti = -9;
    d.time.forEach((date, i) => {
      const t = thr(date), p = pr[i], s = sm[i];
      if (p != null && (stats.max_precip_mm == null || p > stats.max_precip_mm)) { stats.max_precip_mm = p; stats.max_precip_date = date; }
      if (s != null && (stats.max_soil == null || s > stats.max_soil)) stats.max_soil = s;
      const soilWet = s != null && t.soil != null && s >= t.soil;
      const prevWet = i > 0 && sm[i - 1] != null && t.soil != null && sm[i - 1] >= t.soil;
      if (soilWet) stats.wet_soil_days += 1;
      if (tmin[i] != null && tmax[i] != null && tmin[i] < 0 && tmax[i] > 0) stats.freeze_thaw_days += 1;
      if (p != null && t.rain != null && p >= t.rain) {
        events.push({ date, kind: 'heavy_rain', text: r1(p) + ' mm rain vs ' + t.basis + ' 95th percentile ' + r1(t.rain) + ' mm' + (soilWet || prevWet ? ', on soil above its 90th-percentile moisture' : '') });
      } else if (p != null && t.rain != null && p >= 0.5 * t.rain && (soilWet || prevWet)) {
        events.push({ date, kind: 'rain_on_saturated_soil', text: r1(p) + ' mm rain on soil at ' + s + ' m3/m3 vs ' + t.basis + ' 90th percentile ' + t.soil + ' m3/m3' });
      }
      if (i >= 2 && t.rain != null) {
        const sum3 = (pr[i] || 0) + (pr[i - 1] || 0) + (pr[i - 2] || 0);
        if (sum3 >= 2 * t.rain && i - lastMulti > 2) {
          lastMulti = i;
          events.push({ date, kind: 'multi_day_rain', text: '3-day rain total ' + r1(sum3) + ' mm vs ' + r1(2 * t.rain) + ' mm (2x ' + t.basis + ' 95th percentile)' });
        }
      }
    });
    if (events.length) {
      state = 'escalated';
      summary = events.length + ' heavy-weather event(s) in the next ' + stats.days + ' days on flagged ground. First: ' + events[0].date + ', ' + events[0].text + '.';
    } else if (stats.wet_soil_days > 0) {
      state = 'watch';
      summary = 'Soil above its 90th-percentile moisture on ' + stats.wet_soil_days + ' of ' + stats.days + ' days, no heavy rain forecast.';
    } else {
      state = 'clear';
      summary = 'No forecast rain or soil moisture above seasonal thresholds in the next ' + stats.days + ' days (max rain ' + r1(stats.max_precip_mm) + ' mm).';
    }
  }
  for (const s of c.segments) {
    // Near-term heavy weather on flagged ground is the only automatic trigger. A failed forecast is logged as
    // unverified for every flagged segment, red included, so it is never mistaken for clear.
    out.push({ json: {
      ...s,
      state,
      route: state === 'escalated' ? 'candidate' : state === 'unverified' ? 'unverified' : 'none',
      escalate: false,
      priority: state === 'escalated' ? 'high' : 'normal',
      trigger_source: 'workflow3',
      summary: summary + ' Source: ' + forecastSource + '.',
      events,
      forecast_error: state === 'unverified' ? summary : null,
      near_term_json: JSON.stringify({ state, events, stats, cell: c.cell, forecast_source: forecastSource, checked_at: now }),
      checked_at: now,
    } });
  }
});
// Cap and dry-run. Candidates are ranked by score; each one leaves with an explicit, logged reason.
const cand = out.filter((o) => o.json.route === 'candidate').sort((a, b) => (b.json.score || 0) - (a.json.score || 0));
cand.forEach((o, i) => {
  const j = o.json;
  j.draft_rank = i + 1; j.draft_candidates = cand.length; j.dry_run = DRY_RUN; j.max_drafts_per_run = MAX_DRAFTS_PER_RUN;
  if (i >= MAX_DRAFTS_PER_RUN) { j.route = 'preview'; j.preview_reason = 'suppressed: over the cap of ' + MAX_DRAFTS_PER_RUN + ' drafts per run'; }
  else if (DRY_RUN) { j.route = 'preview'; j.preview_reason = 'dry run: would draft a work order, Workflow 4 not called'; }
  else { j.route = 'escalated'; j.escalate = true; }
});
return out;

// Turns a flagged segment from Workflow 2 or 3 into a fact sheet. Only these facts reach the AI.
// Work orders: red / red-uncertain always; amber only when Workflow 3 escalates it (heavy weather forecast, priority high).
const RED = ['red', 'red-uncertain'];
const LF = String.fromCharCode(10);
const parse = (v, dflt) => {
  if (v == null || v === '') return dflt;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return dflt; }
};
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const seg = String(j.segment_id || '').trim();
  const tier = String(j.tier || '').trim();
  const escalatedAmber = tier === 'amber' && j.priority === 'high';
  if (!seg || !(RED.includes(tier) || escalatedAmber)) continue;
  const drivers = parse(j.drivers_json, []);
  const near = parse(j.near_term_json, null);
  const facts = [
    'Segment: ' + seg,
    'Horizon: ' + (j.horizon || 'y10'),
    'Risk score (0-100): ' + (j.score != null && j.score !== '' ? j.score : 'not available'),
    'Risk tier: ' + tier,
    'Model agreement on extreme-rain direction: ' + (j.agreement || 'not available'),
  ];
  if (j.slope_pct != null && j.slope_pct !== '') facts.push('Slope: ' + j.slope_pct + '% grade');
  (Array.isArray(drivers) ? drivers : []).slice(0, 3).forEach((d, k) => {
    if (!d || !d.label) return;
    let line = 'Driver ' + (k + 1) + ': ' + d.label;
    if (d.key === 'slope') line += ', ' + d.change + '% grade';
    else if (d.change != null) line += ', change ' + d.change + '%';
    if (d.base != null) line += ', baseline ' + d.base + ' per year';
    if (d.proj != null) line += ', projected ' + d.proj + ' per year';
    facts.push(line);
  });
  if (near && near.events && near.events.length) {
    near.events.slice(0, 3).forEach((e) => facts.push('Near-term forecast (' + e.date + '): ' + e.text));
  }
  const top = (Array.isArray(drivers) && drivers[0]) || null;
  out.push({ json: {
    work_order_id: 'WO-' + seg + '-' + Date.now().toString(36).toUpperCase(),
    segment_id: seg,
    tier,
    horizon: j.horizon || 'y10',
    score: j.score != null && j.score !== '' ? Number(j.score) : null,
    agreement: j.agreement || null,
    slope_pct: j.slope_pct != null && j.slope_pct !== '' ? Number(j.slope_pct) : null,
    priority: j.priority === 'high' ? 'high' : 'normal',
    trigger_source: j.trigger_source || 'workflow',
    top_driver_key: top ? top.key : null,
    top_driver_label: top ? top.label : null,
    facts,
    facts_text: facts.join(LF),
  } });
}
return out;

// Accept the AI text only if it is exactly two sentences and every number in it appears in the facts.
// Otherwise fall back to a fixed template built from the same facts.
const f = $('WF4 · Build facts').item.json;
const raw = String(($json && $json.text) || '').replace(/\s+/g, ' ').trim();
const sentences = raw ? raw.split(/(?<=[.!?])\s+(?=[A-Z0-9])/).filter((s) => s.trim()) : [];
const nums = raw.match(/\d+(?:\.\d+)?/g) || [];
const unknownNums = nums.filter((n) => !f.facts_text.includes(n));
const INSPECT = {
  rain: 'drainage paths, culverts and surface erosion along the right-of-way',
  freezeThaw: 'frost heave, depth of cover and coating damage at exposed sections',
  saturation: 'saturated ground, seepage and early signs of soil creep',
  vegetation: 'vegetation loss and bare-soil erosion on the right-of-way',
  slope: 'tension cracks, scarps and ground movement on the steepest part of the segment',
};
let summary = raw, source = 'ai';
if (sentences.length !== 2 || unknownNums.length > 0) {
  source = 'template';
  const drv = f.top_driver_label ? f.top_driver_label + ' is the primary risk driver' : 'The combined risk factors drive the score';
  summary = drv + ' for ' + f.segment_id + ' (' + f.horizon + ' score ' + (f.score != null ? f.score : 'n/a') + ', tier ' + f.tier + ', model agreement ' + (f.agreement || 'n/a') + ').' +
    ' Field crews should first inspect ' + (INSPECT[f.top_driver_key] || 'the segment for ground movement and drainage problems') + '.';
}
return { json: {
  work_order_id: f.work_order_id,
  segment_id: f.segment_id,
  status: 'pending_approval',
  priority: f.priority,
  trigger_source: f.trigger_source,
  tier: f.tier,
  horizon: f.horizon,
  score: f.score,
  summary,
  summary_source: source,
  rejected_ai_text: source === 'template' ? raw : null,
  facts_json: JSON.stringify(f.facts),
  resume_url: $execution.resumeUrl,
  execution_id: String($execution.id),
  drafted_at: new Date().toISOString(),
} };

// Runs when the approval gate resumes: an operator decision, or the 14-day timeout.
const wo = $('WF4 · Check summary').item.json;
const b = ($json && ($json.body || ($json.decision ? $json : null))) || {};
const d = String(b.decision || '').toLowerCase();
const status = d === 'approve' ? 'approved' : d === 'reject' ? 'rejected' : 'expired';
return { json: {
  work_order_id: wo.work_order_id,
  segment_id: wo.segment_id,
  status,
  decided_by: status === 'expired' ? 'system:timeout' : String(b.by || 'operator'),
  decision_note: String(b.note || ''),
  decided_at: new Date().toISOString(),
} };

// Every dashboard click lands here. Unknown actions are refused; tier overrides need a reason.
const req = $input.first().json || {};
const b = req.body || {};
const ALLOWED = ['approve_work_order', 'reject_work_order', 'override_tier'];
const TIERS = ['green', 'amber', 'red', 'red-uncertain', 'unverified'];
const action = String(b.action || '').trim();
const segment = String(b.segment || b.segment_id || '').trim();
const by = String(b.by || b.user || '').trim() || 'operator';
const details = b.details && typeof b.details === 'object' ? b.details : {};
const reason = String(details.reason || '').trim();
const toTier = String(details.to || '').trim();
// The dashboard sends horizon as 5 or 10; the API also accepts 'y5' / 'y10'.
const hRaw = String(details.horizon != null && details.horizon !== '' ? details.horizon : '10').trim().toLowerCase();
const horizon = hRaw === '5' || hRaw === 'y5' ? 'y5' : hRaw === '10' || hRaw === 'y10' ? 'y10' : '';
const errors = [];
if (!ALLOWED.includes(action)) errors.push('unknown action "' + action + '"; allowed: ' + ALLOWED.join(', '));
if (!segment) errors.push('missing segment');
if (action === 'override_tier') {
  if (!reason) errors.push('override_tier needs a non-empty details.reason');
  if (!TIERS.includes(toTier)) errors.push('override_tier needs details.to, one of: ' + TIERS.join(', '));
  if (!horizon) errors.push('details.horizon must be 5, 10, y5 or y10');
}
return [{ json: {
  ok: errors.length === 0,
  error: errors.length ? errors.join('; ') : null,
  action,
  segment,
  by,
  decision: action === 'approve_work_order' ? 'approve' : action === 'reject_work_order' ? 'reject' : '',
  work_order_id: String(b.work_order_id || details.work_order_id || '').trim(),
  reason,
  to_tier: toTier,
  horizon,
  note: String(details.note || reason || '').trim(),
  details_json: JSON.stringify({ details, score: b.score != null ? b.score : null }),
  score: b.score != null && b.score !== '' && Number.isFinite(Number(b.score)) ? Number(b.score) : null,
  // Shown to the manager when they pressed Approve (dashboard). Free text is trimmed and length-capped.
  req_tier: TIERS.includes(String(details.tier || '')) ? String(details.tier) : '',
  req_horizon: String(details.stop || '') === 'y5' ? 'y5' : 'y10',
  req_priority: /^P[123]$/.test(String(details.priority || '')) ? String(details.priority) : '',
  req_due: /^\d{4}-\d{2}-\d{2}$/.test(String(details.dueBy || '')) ? String(details.dueBy) : '',
  req_hazard: String(details.hazard || '').slice(0, 40),
  req_why: String(details.why || '').slice(0, 300),
  req_checks: Array.isArray(details.checks) ? details.checks.slice(0, 8).map((x) => String(x).slice(0, 240)) : [],
  req_map: /^https:\/\/www\.(openstreetmap\.org\/|google\.com\/maps[\/?])/.test(String(details.mapUrl || '')) ? String(details.mapUrl).slice(0, 200) : '',
  received_at: new Date().toISOString(),
} }];

// One item out: the order that blocks a new draft for this segment, or {} if none.
// Blocks when an order is pending approval, or was approved in the last 7 days.
const DAY = 24 * 3600 * 1000;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const pending = rows.find((r) => r.status === 'pending_approval');
const recent = rows
  .filter((r) => r.status === 'approved' && r.decided_at && Date.now() - new Date(r.decided_at).getTime() < 7 * DAY)
  .sort((a, b) => String(b.decided_at).localeCompare(String(a.decided_at)))[0];
const b = pending || recent;
return [{ json: b ? { ...b, block_reason: pending ? 'pending_approval' : 'approved_within_7_days' } : {}, pairedItem: { item: 0 } }];

// Manager-requested inspection: the integrity manager approved a segment that has no automatic draft.
// One item out. If this segment already has an order approved in the last 7 days, or one pending, reuse it (no duplicate row).
// 'approved' here means recorded in corridor_work_orders. Nothing is emailed and no crew is dispatched by this workflow.
const v = $('WF4 · Validate action').first().json;
const DAY = 24 * 3600 * 1000;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.work_order_id);
const dup = rows.filter((r) => r.status === 'pending_approval' || (r.status === 'approved' && r.decided_at && Date.now() - new Date(r.decided_at).getTime() < 7 * DAY))
  .sort((a, b) => String(b.drafted_at || '').localeCompare(String(a.drafted_at || '')))[0];
const now = new Date().toISOString();
if (dup) return [{ json: { duplicate: true, work_order_id: dup.work_order_id, segment_id: v.segment, status: dup.status, block_reason: dup.status === 'approved' ? 'approved_within_7_days' : 'pending_approval' } }];
const facts = ['Segment: ' + v.segment, 'Requested by: ' + v.by + ' (integrity manager, from the dashboard)', 'Horizon: ' + v.req_horizon,
  'Risk score (0-100): ' + (v.score != null ? v.score : 'not available'), 'Risk tier: ' + (v.req_tier || 'not available')];
if (v.req_hazard) facts.push('Worst hazard: ' + v.req_hazard);
if (v.req_why) facts.push('Main driver: ' + v.req_why);
if (v.req_due) facts.push('Due by: ' + v.req_due + (v.req_priority ? ' (' + v.req_priority + ')' : ''));
v.req_checks.forEach((c, i) => facts.push('Check ' + (i + 1) + ': ' + c));
if (v.req_map) facts.push('Location: ' + v.req_map);
facts.push('Next step: queued email handoff when SMTP delivery is configured, or CSV export for the inspection coordinator. No crew dispatch.');
return [{ json: {
  duplicate: false,
  work_order_id: 'WO-' + v.segment + '-' + Date.now().toString(36).toUpperCase(),
  segment_id: v.segment, status: 'approved', priority: v.req_priority === 'P1' ? 'high' : 'normal', trigger_source: 'manager',
  tier: v.req_tier || 'unverified', horizon: v.req_horizon, score: v.score,
  summary: 'Manager-requested inspection of ' + v.segment + (v.req_why ? '. ' + v.req_why : '') + '.' + (v.req_checks[0] ? ' First check: ' + v.req_checks[0] : ''),
  facts_json: JSON.stringify(facts), drafted_at: now, decided_at: now, decided_by: v.by, decision_note: v.note || 'approved from the dashboard',
} }];

// ==================================================================
// TERRACORRIDOR SHARED ADAPTER PRELUDE (identical copy in W5 and W6)
// All upstream mappings (W1-W4), fixtures and the build-score formula
// live here. Edit ONLY this block to integrate W2/W3/W4.
// ==================================================================
const integrations = {
  demoMode: false,                       // true => mock fixtures allowed (always labelled demo_fixture)
  corridorId: "ab-strathcona-demo",
  segmentsTable: "euUFpWZEDrrDJOkc",  // W1 corridor_segments
  predictionsTable: "7T6RlFe9HRFOfkCD",  // W2 corridor_predictions (one row per segment and horizon)
  baselinesTable: "LckNoZvtBFwDnwM3",  // W2 corridor_baselines (slope, NDVI, baseline days)
  alertsTable: "sPlAgvMC7Q6sFHho",  // W3 near-term state lives in corridor_watch
  auditTable: "fWeMlbL9wQ5I7m3N",  // W4 corridor_work_orders (approval status per segment)
  buildTable: "E1GpvXaFTP4qLjsW",  // W5 corridor_build
  reportsTable: "T0PP8Zebw0vWU5KW",  // W5 corridor_reports
